<script setup>
import { ref, computed, onMounted } from 'vue'
import './teaching/workspace.css'
const props=defineProps({api:Function})
const users=ref([]),classes=ref([]),error=ref(''),notice=ref(''),loading=ref(false),tab=ref('users'),filter=ref('all'),search=ref(''),pending=ref(null),members=ref(null),selectedClass=ref(null),classTitle=ref(''),teacherId=ref(''),editing=ref(null)
const teachers=computed(()=>users.value.filter(u=>u.role==='teacher'))
const visible=computed(()=>users.value.filter(u=>(filter.value==='all'||(filter.value==='pending'?u.teacherStatus==='pending':u.role===filter.value))&&`${u.username} ${u.displayName}`.includes(search.value)))
async function fetchData(){const result=await Promise.all([props.api('/admin/users'),props.api('/admin/classes')]);users.value=result[0];classes.value=result[1]}
async function run(fn,message=''){if(loading.value)return;loading.value=true;error.value='';notice.value='';try{await fn();notice.value=message}catch(e){error.value=e.message}finally{loading.value=false}}
function review(user,decision){run(async()=>{await props.api(`/admin/users/${user.id}/review`,{method:'POST',body:JSON.stringify({decision})});await fetchData()},'申请已处理。')}
function changeRole(){run(async()=>{await props.api(`/admin/users/${pending.value.user.id}/role`,{method:'PUT',body:JSON.stringify({role:pending.value.role})});pending.value=null;await fetchData()},'权限已更新，用户刷新页面后进入对应工作台。')}
function saveClass(){run(async()=>{await props.api('/admin/classes'+(editing.value?'/'+editing.value:''),{method:editing.value?'PUT':'POST',body:JSON.stringify({title:classTitle.value,teacherId:teacherId.value})});editing.value=null;classTitle.value='';teacherId.value='';await fetchData()},'班级信息已保存。')}
function showMembers(c){run(async()=>{members.value=await props.api(`/admin/classes/${c.id}/members`);selectedClass.value=c})}
onMounted(()=>run(fetchData))
</script>
<template><section class="teaching-workspace admin-console"><div class="work-heading"><div><h1>管理工作台</h1><p>管理班级、审核教师申请并分配师生权限。</p></div><button class="work-button" :disabled="loading" @click="run(fetchData)">刷新列表</button></div><nav class="work-tabs" aria-label="管理功能"><button :class="{active:tab==='users'}" @click="tab='users'">师生权限</button><button :class="{active:tab==='classes'}" @click="tab='classes'">班级管理</button></nav><p v-if="error" class="work-error" role="alert">{{error}}</p><p v-if="notice" class="work-notice" role="status">{{notice}}</p><p v-if="loading" role="status">正在处理…</p>
<template v-if="tab==='users'"><div class="work-heading"><h2>用户与教师审核</h2><span class="work-small">显示最近 200 个账号</span></div><div class="work-row work-footer"><label>查找用户<input v-model="search" placeholder="输入账号或昵称"/></label><label>身份筛选<select v-model="filter"><option value="all">全部账号</option><option value="teacher">教师</option><option value="student">学生</option><option value="pending">待审核教师</option></select></label></div><div v-if="pending" class="work-notice"><p>将 {{pending.user.displayName}}（{{pending.user.username}}）设置为{{pending.role==='teacher'?'教师':'学生'}}？账号将按新身份访问功能，原有数据保留。</p><div class="work-actions"><button class="work-primary" :disabled="loading" @click="changeRole">确认修改权限</button><button class="work-button" :disabled="loading" @click="pending=null">取消</button></div></div><div class="admin-table work-footer"><table><thead><tr><th>用户</th><th>账号</th><th>身份</th><th>教师申请</th><th>操作</th></tr></thead><tbody><tr v-for="u in visible" :key="u.id"><td>{{u.displayName}}</td><td>{{u.username}}</td><td>{{{student:'学生',teacher:'教师',admin:'管理员'}[u.role]}}</td><td>{{{none:'未申请',pending:'待审核',approved:'已通过',rejected:'未通过'}[u.teacherStatus]}}</td><td><template v-if="u.teacherStatus==='pending'&&u.role!=='admin'"><button :disabled="loading" @click="review(u,'approve')">通过申请</button><button :disabled="loading" @click="review(u,'reject')">不通过</button></template><button v-else-if="u.role==='student'" :disabled="loading" @click="pending={user:u,role:'teacher'}">设为教师</button><button v-else-if="u.role==='teacher'" :disabled="loading" @click="pending={user:u,role:'student'}">设为学生</button><span v-else class="work-small">管理员账号</span></td></tr></tbody></table><p v-if="!visible.length&&!loading" class="work-empty">暂无符合条件的账号。</p></div></template>
<template v-else><div class="work-heading"><h2>班级管理</h2><span class="work-small">显示最近 200 个班级</span></div><form class="work-card work-form" @submit.prevent="saveClass"><fieldset :disabled="loading"><h3>{{editing?'修改班级名称':'创建班级并分配教师'}}</h3><div class="work-row"><label>班级名称<input v-model="classTitle" required maxlength="150"/></label><label v-if="!editing">负责教师<select v-model="teacherId" required><option value="" disabled>选择已开通权限的教师</option><option v-for="t in teachers" :key="t.id" :value="t.id">{{t.displayName}}（{{t.username}}）</option></select></label></div><div class="work-actions"><button class="work-primary">{{editing?'保存名称':'创建班级'}}</button><button v-if="editing" type="button" class="work-button" @click="editing=null;classTitle=''">取消编辑</button></div></fieldset></form><div class="admin-table"><table><thead><tr><th>班级</th><th>负责教师</th><th>学生人数</th><th>操作</th></tr></thead><tbody><tr v-for="c in classes" :key="c.id"><td>{{c.title}}</td><td>{{c.teacherName}}（{{c.teacherUsername}}）</td><td>{{c.memberCount}}</td><td><button :disabled="loading" @click="showMembers(c)">查看成员</button><button :disabled="loading" @click="editing=c.id;classTitle=c.title">修改名称</button></td></tr></tbody></table><p v-if="!classes.length&&!loading" class="work-empty">暂无班级，可在上方创建并指定负责教师。</p></div><section v-if="members" class="work-card work-footer"><h3>{{selectedClass.title}} · 成员</h3><p v-if="!members.length">暂无学生加入。</p><ul><li v-for="m in members" :key="m.id">{{m.displayName}}（{{m.username}}）</li></ul></section></template></section></template>
<style scoped>.admin-console h1{font-size:28px;margin:0}.admin-console td button{margin:4px 12px 4px 0;padding:6px 0}.admin-console table{min-width:620px}.admin-console .admin-table{overflow-x:auto}</style>
